  ({ className, shortcut, showShortcut = !!shortcut, placeholder = 'Search', disabled, ...props }, ref) => {
    return (
      <div
        data-disabled={disabled ? '' : undefined}
        className={cn(
          'flex items-center gap-sm',
          'bg-secondary border border-solid border-border-primary',
          'rounded-soft',
          'pl-lg pr-md py-md',
          'ds-min-w-search-box',
          'ds-motion-state',
