/*
 * Composite text-style classes — the full typographic intent of a role in one
 * class, including font-variation-settings, which has no Tailwind utility.
 *
 * Deliberately in `components`, NOT `utilities`: BaseText applies these as role
 * DEFAULTS, the ambient layer under everything else. Typography changes go
 * through BaseText props, which are written inline and so outrank the role
 * class; typography utilities are not a supported override, in DS code or in a
 * consuming app.
 *
 * Nothing here sets line-height: leading is left to inherit, and the consuming
 * app sets it per instance with the lineHeight prop.
 */
@layer components {
  /* .ds-chat-prose (dooph-component-tokens.css) re-spells four of these roles
   * by hand: title (h1), heading (h2), subheading (h3), mono (code). A
   * property added to one of those roles must be added there too. */
  .text-style-button {
    font-family: var(--ui-font-button);
    font-optical-sizing: auto;
    font-size: var(--ui-text-body);
    font-style: normal;
    font-weight: var(--ui-weight-button);
    font-variation-settings: var(--ui-font-var-button);
  }

  .text-style-body {
    font-family: var(--ui-font-body);
    font-optical-sizing: auto;
    font-size: var(--ui-text-body);
    font-style: normal;
    font-weight: var(--ui-weight-body);
    font-variation-settings: var(--ui-font-var-body);
    letter-spacing: var(--ui-tracking-body);
  }

  /* The hero-scale pair. Each is byte-identical to its base role apart from the
   * size token — same family, weight, axes and tracking — so they read as the
   * same voice set larger, not as a second one. Keep them in sync by hand if a
   * base role gains a property; they are spelled out rather than composed
   * because BaseText applies exactly one role class per element, so each must
   * stand alone. */
  .text-style-hero-body {
    font-family: var(--ui-font-body);
    font-optical-sizing: auto;
    font-size: var(--ui-text-hero-body);
    font-style: normal;
    font-weight: var(--ui-weight-body);
    font-variation-settings: var(--ui-font-var-body);
    letter-spacing: var(--ui-tracking-body);
  }

  .text-style-hero-button {
    font-family: var(--ui-font-button);
    font-optical-sizing: auto;
    font-size: var(--ui-text-hero-button);
    font-style: normal;
    font-weight: var(--ui-weight-button);
    font-variation-settings: var(--ui-font-var-button);
  }

  /* Mono deliberately mirrors button's size and weight (both tokens alias it)
   * so a mono run set beside a button label sits at the same optical scale.
   * The MONO axis is named explicitly — see the token's note on why trusting
   * the family default is not enough. */
  .text-style-mono {
    font-family: var(--ui-font-mono);
