  /* ShimmerText — gradient masked to glyphs (incl. descendants); children must
   * not set an explicit text color while shimmering. */
  .ds-shimmer-text {
    background: linear-gradient(
      100deg,
      var(--ui-shimmer-base) 40%,
      var(--ui-shimmer-highlight) 50%,
      var(--ui-shimmer-base) 60%
    );
