    .ds-roll-hover-in {
      display: none;
    }
    .ds-roll-hover:hover .ds-roll-hover-out,
    .group:hover .ds-roll-hover .ds-roll-hover-out,
    .ds-roll-hover[data-active="true"] .ds-roll-hover-out {
      transform: none;
      filter: none;
      opacity: 1;
    }
  }

  /* UnderlineLinkText — a "sliding underline". The line is a currentColor
   * gradient in background (not text-decoration or a pseudo-element) so it
   * tracks the element's own `color` — including hover/active changes on this
   * element or an ancestor. Color must live on UnderlineLinkText or above; a
   * child that sets its own text color will not recolor the underline.
   *
   * Position is `calc(1em + offset)` from the top of each line box (with
   * box-decoration-break: clone so wrapped lines each get their own line), which
   * sits just under the em square like a native text-decoration underline —
   * independent of leading. Stroke weight is `--ds-underline-thickness` (from the
   * `thickness` prop) falling back to the token; offset is likewise
   * `--ds-underline-offset` → token. On hover it runs a one-shot two-phase sweep
   * — out to the right, then back in from the left. */
  .ds-underline-link {
    background-image: linear-gradient(currentColor, currentColor);
    background-repeat: no-repeat;
    /* Longhands so the wipe keyframes can retarget only x without resetting y. */
    background-position-x: 0%;
    background-position-y: calc(1em + var(--ds-underline-offset, var(--ui-underline-link-offset)));
    background-size: 100% var(--ds-underline-thickness, var(--ui-underline-link-thickness));
    -webkit-box-decoration-break: clone;
    box-decoration-break: clone;
  }
  .ds-underline-link:hover,
  .group:hover .ds-underline-link,
  .ds-underline-link[data-active="true"] {
    animation: ds-underline-wipe var(--ui-motion-duration-slowest)
      var(--ui-motion-ease-enter) both;
  }

  /* RollingDigitsText — 2D cash-register digit roll (no blur, no 3D).
   *
   * ## structure
   * Each digit is a WHEEL: a static 0-9 column clipped to one line box and
   * positioned by --ds-digit. Around it, every animated unit — wheel or
   * grouping separator — is a slot that owns an EXPLICIT width, because that is
   * the only thing `width` can animate from and to.
   *
   * ## why a transition for the roll and an animation for enter/exit
   * The roll is a TRANSITION on transform. Re-applying a class that is already
   * present does not restart an animation, which is why the original
   * keyframe-based roll fired on roughly every other change; a transition on a
   * changed value always runs, and an interrupted one retargets from wherever
   * the wheel currently sits.
   *
   * Enter and exit are ANIMATIONS for the mirror-image reason: each runs
   * exactly once in an element's life, on mount and on unmount. A mount
   * animation needs no JavaScript at all to start — which is what let the
   * previous version's double-requestAnimationFrame reveal be deleted outright.
   *
   * ## why one keyframe pair covers both wheels and separators
   * A one-sided keyframe takes its missing half from the element's own computed
   * style, so `from { width: 0 }` resolves its `to` as
   * --ui-rolling-digits-digit-width on a wheel and as
   * --ui-rolling-digits-separator-width on a separator. Do not add explicit
   * `to` widths here; that genericity is the whole trick.
   *
   * ## the baseline invariant
   * The hidden "0" spacer is what makes alignment work without magic numbers:
   * it is an ordinary in-flow glyph, so it supplies the wheel's baseline. The
   * clip is absolutely positioned against it — exactly 1lh tall — and each of
   * the ten column children is also 1lh, so -10% per digit lands precisely. A
   * clipped inline-block takes its baseline from its bottom margin edge, which
   * is why an `overflow: hidden` wheel could not be aligned at any value of
   * 1em. The spacer must stay in flow and stay `visibility: hidden` (never
   * `display: none`) for that reason, even though the width is now explicit. */
  .ds-rolling-digits {
    display: inline-block;
  }
  .ds-rolling-digits-figure {
    display: inline-flex;
    align-items: baseline;
    /* Load-bearing, not cosmetic: the fixed slot width below is only correct
     * while every figure shares one advance. */
    font-variant-numeric: tabular-nums;
    /* A figure must never wrap. The decimals wrapper is a flex item whose child
     * is an INLINE role span, so once the decimals are large enough to be
     * squeezed the inline content breaks across line boxes and they land on
     * their own line — which is exactly what happened at hero size before this
     * rule existed. */
    white-space: nowrap;
  }

  /* The animated unit. Wheels and separators differ only in resting width.
   * Width and opacity are separate animations on purpose: opacity is scaled to
   * a FRACTION of the duration so an arriving glyph — drawn at its full width,
   * and so overflowing its still-narrow slot — is opaque before it stops
   * overlapping its neighbour. */
  .ds-rolling-digits-wheel,
  .ds-rolling-digits-sep {
    display: inline-block;
    flex: 0 0 auto;
    font-variant-numeric: tabular-nums;
  }
  .ds-rolling-digits-wheel {
    position: relative;
    width: var(--ui-rolling-digits-digit-width);
  }
  .ds-rolling-digits-sep {
    /* Fixed rather than natural because `width` cannot animate from `auto`.
     * Overflow stays visible and the glyph is centred, so a token narrower than
     * the face's comma reads tight, never clipped. */
    width: var(--ui-rolling-digits-separator-width);
    text-align: center;
  }
  .ds-rolling-digits-wheel[data-entering],
  .ds-rolling-digits-sep[data-entering] {
    animation:
      ds-rolling-digits-in var(--ui-motion-duration-slow)
        var(--ui-motion-ease-enter),
      ds-rolling-digits-fade-in
        calc(
          var(--ui-motion-duration-slow) *
            var(--ui-rolling-digits-opacity-ratio)
        )
        var(--ui-motion-ease-enter);
  }
  /* Declared after the entering rule so it wins on source order when a wheel
   * that entered earlier is now leaving — both are single-class selectors.
   * `forwards` holds the collapsed state for the frame between animationend and
   * React dropping the node. */
  .ds-rolling-digits-wheel[data-exiting],
  .ds-rolling-digits-sep[data-exiting] {
    animation:
      ds-rolling-digits-out var(--ui-motion-duration-base)
        var(--ui-motion-ease-enter) forwards,
      ds-rolling-digits-fade-out
        calc(
          var(--ui-motion-duration-base) *
            var(--ui-rolling-digits-opacity-ratio)
        )
        var(--ui-motion-ease-enter) forwards;
  }

  /* Sets the wheel's baseline. Never visible; never removed from flow. */
  .ds-rolling-digits-space {
    visibility: hidden;
  }
  /* Pinned to the slot width rather than stretched to `inset: 0`, so a glyph is
   * never sliced horizontally while its slot is mid-animation: it sits at its
   * final position and overflows a narrower slot, with the fade covering the
   * overlap.
   *
   * Then widened 20% and re-centred on the slot. This clip exists to bound the
   * roll VERTICALLY; its horizontal edges are incidental, and 1ch is a hair
   * under the true tabular advance (see the token's note), so a flush box would
   * shave a fraction of a pixel off both side bearings for no benefit. */
  .ds-rolling-digits-clip {
    position: absolute;
    left: calc(var(--ui-rolling-digits-digit-width) * -0.1);
    top: 0;
    bottom: 0;
    width: calc(var(--ui-rolling-digits-digit-width) * 1.2);
    overflow: hidden;
    /* aria-hidden, not display:none — selecting the figure would otherwise pick
     * up all ten glyphs per wheel ("0123456789...") alongside the real value
     * from the sr-only span. */
    user-select: none;
  }
  .ds-rolling-digits-col {
    display: block;
    /* Centred so any drift between 1ch and the face's true tabular advance is
     * symmetric per wheel instead of accumulating across the figure. */
    text-align: center;
    transform: translateY(calc(var(--ds-digit, 0) * -10%));
    transition: transform var(--ui-motion-duration-base)
      var(--ui-motion-ease-enter);
    /* At the zero default every delay computes to zero and the figure moves as
     * one. Raising the token cascades right-to-left, ones place leading. */
    transition-delay: calc(var(--ds-place, 0) * var(--ui-rolling-digits-stagger));
  }
  .ds-rolling-digits-col > span {
    display: block;
  }

  /* Sized here, in em of the integer part, rather than by whatever role is
   * passed as `smallDecimalsComponent` — a role brings a fixed px size, which
   * cannot stay proportional across TitleText and HeroText. The wrapper
   * therefore owns the SIZE and the passed role owns family/weight/tracking. */
  .ds-rolling-digits-decimals {
    /* Never let the flex layout shrink this below its content; shrinking is
     * what triggered the wrap described on .ds-rolling-digits-figure. */
    flex: 0 0 auto;
    margin-left: var(--ui-rolling-digits-decimals-gap);
    transform: translateY(calc(-1 * var(--ui-rolling-digits-decimals-rise)));
  }
  /* The SIZE goes on the child, never on the wrapper above. `em` resolves
   * against the element's OWN font-size, so sizing the wrapper would make
   * `decimals-gap` and `decimals-rise` resolve against the decimals instead of
   * the integer part — silently destroying the parent-em invariant those two
   * tokens depend on. Sizing the child leaves the wrapper inheriting the
   * parent. This also overrides the `text-style-*` font-size the passed role
   * brings, which is the point. 1ch and the separator width then resolve
   * against the smaller size, so the decimals' slots scale with it for free. */
  .ds-rolling-digits-decimals > * {
    font-size: var(--ui-rolling-digits-decimals-size);
  }

  /* Reduced motion needs no rule here: the global block in tokens.css
   * collapses the scale and zeroes the stagger, so the roll and the slot
   * enter/exit all become instant. The exit must still RUN rather than be
   * removed — its `animationend` is what unmounts a departing wheel, and
   * `animation: none` would starve it and strand blank slots. */

  /* RollChangeText. Real classes rather than arbitrary `animate-[…]` values so
   * the timing lives on the motion scale — and so reduced motion (the global
   * block in tokens.css) collapses the duration instead of removing the
   * animation. That distinction is
   * load-bearing: each node is retired by its own `animationend`, and
   * `animation: none` would starve that event and strand the old content on
   * screen forever.
   *
   * `will-change` is here because the roll animates `filter: blur()` over text,
   * which is re-rasterized every frame. Without the hint the compositor promotes
   * the node only once the animation is already running, and the cost of that
   * first raster lands inside the first frame or two, where the roll would
   * visibly hitch. Both classes are removed the moment their animation
   * ends (the out node unmounts, the in node drops the class), so neither
   * strands a layer on settled content. */
  /* The soft clip shared by RollChangeText and FadeChangeText (ChangeSwapShell).
   * A vertical mask fades the rolling face out at the top and bottom; a hard
   * `overflow: hidden` would slice the glyphs and their blur halo. The box
   * gets --ui-roll-change-breathe of padding top and bottom, cancelled by an
   * equal negative margin: its margin box (and so its outer size and baseline
   * position in the line) is exactly what it was without either. The fade
   * zones are exactly that breathing room (em stops, not a percentage): the
   * resting line sits wholly in the opaque middle at any line-height, where an
   * 18% stop would dim tall glyphs at a tight leading. The mask also clips to
   * the border box, so nothing paints outside it. */
  .ds-change-swap {
    padding-block: var(--ui-roll-change-breathe);
    margin-block: calc(var(--ui-roll-change-breathe) * -1);
    mask-image: linear-gradient(
      transparent,
      #000 var(--ui-roll-change-breathe),
      #000 calc(100% - var(--ui-roll-change-breathe)),
      transparent
    );
  }
  .ds-roll-change-out {
    animation: ds-roll-out var(--ui-motion-duration-base)
      var(--ui-motion-ease-exit) forwards;
    will-change: transform, filter, opacity;
  }
  .ds-roll-change-in {
    animation: ds-roll-in var(--ui-motion-duration-slow)
      var(--ui-motion-ease-enter) both;
    will-change: transform, filter, opacity;
  }

  /* FadeChangeText — the roll without blur: transform + opacity only, so
   * `will-change` names only those. Classes drop when each half ends (the out
   * node unmounts, the in node loses the class), so neither strands a layer on
   * settled content. Timing matches the roll's, on the motion scale. Reduced
   * motion collapses the scale rather than removing the animation, because
   * `animationend` is what retires each half. */
  .ds-fade-change-out {
    animation: ds-fade-change-out var(--ui-motion-duration-base)
      var(--ui-motion-ease-exit) forwards;
    will-change: transform, opacity;
  }
  .ds-fade-change-in {
    animation: ds-fade-change-in var(--ui-motion-duration-slow)
      var(--ui-motion-ease-enter) both;
    will-change: transform, opacity;
  }

  /* SidebarWithHoverIcon rail. This rule is the icon's entire motion system —
   * the component sets the two targets and reads back what CSS interpolated.
   * Two independent motions: the rail TRAVERSING the frame when `side` flips
   * (`slow`), and pulling out into a chevron on hover (`base`). Hover is the
   * faster of the two because it answers a pointer; the traverse is a state
   * change and carries more weight.
   *
   * Under reduced motion the global block collapses both durations to an
   * instant rather than the transitions being removed: the component's sampling loop
   * terminates when the values reach their targets, so it writes the final
   * path within a frame and stops. */
  .ds-sidebar-rail {
    transition:
      --ds-sidebar-rail-s var(--ui-motion-duration-slow)
        var(--ui-motion-ease-enter),
      --ds-sidebar-rail-h var(--ui-motion-duration-base)
        var(--ui-motion-ease-enter);
  }

  /* MorphRotationShape — CSS owns every duration and curve; the component only
   * samples --ds-shape-morph-step and writes geometry.
   * --ds-shape-morph-target is the input: inline in controlled mode, set by
   * the loop in autoplay, set by an ancestor's state in embedded mode
   * (e.g. group-data-[state=open]:[--ds-shape-morph-target:1]). It is NOT
   * registered, so it inherits from that ancestor, and
   * --ds-shape-morph-nudge (unregistered) is the hover lean input.
   *
   * The step runs on the generated spring (--ui-shape-morph-*, off the
   * scale); the hover lean runs on the scale (`base`, `enter`).
   *
   * Reduced motion: the step's duration is NOT on the scale (and `timing` may
   * set it inline), so the global block cannot reach it. This rule shortens
   * every transition here to the scale's own collapsed value — non-zero,
   * because a zero-length transition fires no transitionrun and embedded mode
   * has no other signal that its target moved. Autoplay and passive spinning
   * are loops and stop outright. */
  .ds-shape-morph {
    --ds-shape-morph-step: var(--ds-shape-morph-target, 0);
    --ds-shape-morph-lean: var(--ds-shape-morph-nudge, 0);
    transition:
      --ds-shape-morph-step var(--ui-shape-morph-duration) var(--ui-shape-morph-ease),
      --ds-shape-morph-lean var(--ui-motion-duration-base)
        var(--ui-motion-ease-enter);
  }
  .ds-shape-morph[data-mode="autoplay"] {
    animation: ds-shape-morph-clock var(--ui-shape-morph-interval) linear infinite;
  }
  .ds-shape-morph-passive-spin {
    transform-box: view-box;
    transform-origin: 50% 50%;
    animation: ds-shape-morph-spin var(--ui-shape-morph-passive-spin-duration)
      linear infinite;
  }
  @media (prefers-reduced-motion: reduce) {
    .ds-shape-morph {
      /* Inside this query the scale is already collapsed, so this is the
       * global reduced duration — one source, not a second literal. */
      transition-duration: var(--ui-motion-duration-fast);
    }
    .ds-shape-morph[data-mode="autoplay"],
    .ds-shape-morph-passive-spin {
      animation: none;
    }
  }

  /* LoadingSpinner — CSS owns the clock; the component owns geometry only,
   * written as inline custom properties on the <svg>:
   *   --ds-spinner-c            circumference of the arc path, user units
   *   --ds-spinner-gap          visual-gap allowance between the arcs,
   *                             as a fraction of one turn
   *   --ds-spinner-sweep-min/-max  the arc's length range, fractions of a turn
   *   --ds-spinner-time-scale   per-size factor on the spin duration
   *
   * Flat: Material's circular indeterminate recipe. The group turns at a
   * constant rate, one turn per --ui-spinner-rotate-duration. On the <svg>,
   * --ds-spinner-grow and --ds-spinner-tail (ds-spinner-dash keyframes, on
   * the standard curve per segment) move the arc along its path: first the
   * head races ahead while the tail creeps (the arc grows to its max sweep),
   * then the tail chases the head, which is held at the end of the first lap
   * (sweep is clipped to 1 − tail), so the arc shrinks to a dot and the cycle
   * restarts from it. Turn and dash run as two independent loops, as in
   * Material.
   *
   * The path is a TWO-lap open circle starting one gap before 12 o'clock, so
   * path position p (in turns along the path) sits p − gap turns past
   * 12 o'clock. The arc covers [gap + tail, gap + tail + sweep] and the track, its
   * complement a gap clear of each end, [tail + sweep + 2·gap, tail + 1]:
   * both stay strictly inside (0, 2) turns, so neither dash ever reaches
   * either end of the path (a dash cut by the path's seam splits in two and
   * its round caps flash). Each dash pattern's gap is the whole path (2C),
   * so no second dash ever appears. Both dashes are positioned in user units
   * (× 1px, which is one user unit inside an SVG).
   *
   * Reduced motion: loops are off the scale, so the global block cannot
   * reach them. The flat arc freezes at its longest, tail at 12 o'clock;
   * the spokes and star stop turning. */
  .ds-spinner-flat {
    animation: ds-spinner-dash var(--ui-spinner-duration)
      var(--ui-motion-ease-standard) infinite;
  }
  .ds-spinner-flat-turn {
    transform-box: view-box;
    transform-origin: 50% 50%;
    animation: ds-spinner-rotate var(--ui-spinner-rotate-duration)
      var(--ui-motion-ease-linear) infinite;
  }
  .ds-spinner-flat-arc {
    --ds-spinner-sweep: min(
      calc(
        var(--ds-spinner-sweep-min) +
          (var(--ds-spinner-sweep-max) - var(--ds-spinner-sweep-min)) *
          var(--ds-spinner-grow)
      ),
      calc(1 - var(--ds-spinner-tail))
    );
  }
  /* Active arc: starts `tail` past 12 o'clock and runs `sweep` of a turn. */
  .ds-spinner-flat-indicator {
    stroke-dasharray:
      calc(var(--ds-spinner-sweep) * var(--ds-spinner-c) * 1px)
      calc(var(--ds-spinner-c) * 2px);
    stroke-dashoffset: calc(
      (var(--ds-spinner-gap) + var(--ds-spinner-tail)) *
        var(--ds-spinner-c) * -1px
    );
  }
  /* Track: the complement, a gap clear of the arc at both ends. */
  .ds-spinner-flat-track {
    stroke-dasharray:
      max(
        0px,
        calc(
          (1 - var(--ds-spinner-sweep) - 2 * var(--ds-spinner-gap)) *
            var(--ds-spinner-c) * 1px
        )
      )
      calc(var(--ds-spinner-c) * 2px);
    stroke-dashoffset: calc(
      (
          var(--ds-spinner-tail) + var(--ds-spinner-sweep) + 2 *
            var(--ds-spinner-gap)
        ) *
        var(--ds-spinner-c) * -1px
    );
  }
  /* Spokes and star: a constant linear turn of an inner group. */
  .ds-spinner-spin {
    transform-box: view-box;
    transform-origin: 50% 50%;
    animation: ds-spinner-rotate
      calc(var(--ui-spinner-spokes-duration) * var(--ds-spinner-time-scale, 1))
      var(--ui-motion-ease-linear) infinite;
  }
  @media (prefers-reduced-motion: reduce) {
    .ds-spinner-flat {
      animation: none;
      --ds-spinner-grow: 1;
      --ds-spinner-tail: 0;
    }
    .ds-spinner-flat-turn,
    .ds-spinner-spin {
      animation: none;
    }
  }

  /* DropdownCaret. State is read from the nearest .ds-dropdown-caret-host
   * (the trigger root): Radix data-state, :hover, and the disabled forms.
   * The shape is painted by currentColor, so every state is a colour here. */
  .ds-dropdown-caret {
    --ds-dropdown-caret-frame: calc(var(--ui-height-button) - var(--ui-spacing-md));
    /* Closed: the primary button's background. */
    color: var(--ui-color-primary);
    transition: color var(--ui-motion-duration-base) var(--ui-motion-ease-enter);
  }
  .ds-dropdown-caret-chevron {
    transition:
      rotate var(--ui-shape-morph-duration) var(--ui-shape-morph-ease),
      color var(--ui-motion-duration-base) var(--ui-motion-ease-enter);
  }
  /* Expressive detail: the caret's SHAPE, read from --ui-caret-shape-scale
   * (an expression token; the practical preset sets it to 0). Every read of it
   * lives in a .ds-expr-caret-shape rule.
   *   1  the signature caret: a square the trigger's height, the morphing
   *      shape in a frame of height-button minus spacing-md, and the chevron in
   *      the primary FOREGROUND, because it sits on the shape.
   *   0  a plain chevron: no frame (the shape fills the frame, so it draws
   *      nothing), the root shrinks to the chevron plus a trailing inset that
   *      mirrors the host's leading pl-md (+1px for the -mr-px pull over
   *      the border), and the chevron takes the trigger's text colour.
   * Values in between interpolate; 0 and 1 are the designed settings. The
   * frame may be narrower than the chevron: it overflows centred, and the
   * root's own width is what lays out. */
  .ds-expr-caret-shape {
    width: calc(
      var(--ui-height-button) * var(--ui-caret-shape-scale) +
        (var(--ui-icon-rg) + var(--ui-spacing-md) + 1px) *
        (1 - var(--ui-caret-shape-scale))
    );
    padding-inline-end: calc(
      (var(--ui-spacing-md) + 1px) * (1 - var(--ui-caret-shape-scale))
    );
  }
  .ds-expr-caret-shape .ds-dropdown-caret-frame {
    width: calc(var(--ds-dropdown-caret-frame) * var(--ui-caret-shape-scale));
    height: calc(var(--ds-dropdown-caret-frame) * var(--ui-caret-shape-scale));
  }
  .ds-expr-caret-shape .ds-dropdown-caret-chevron {
    color: color-mix(
      in srgb,
      var(--ui-color-primary-foreground)
        clamp(0%, calc(var(--ui-caret-shape-scale) * 100%), 100%),
      var(--ui-color-secondary-foreground)
    );
  }
  /* Expressive detail: the hover NUDGE, read from --ui-caret-nudge (an
   * expression token, following --ui-shape-morph-nudge by default; the
   * practical preset sets it to 0). */
  .ds-dropdown-caret-host:hover:not(:disabled):not([aria-disabled="true"]):not([data-disabled])
    .ds-expr-caret-nudge {
    --ds-shape-morph-nudge: var(--ui-caret-nudge);
  }
  .ds-dropdown-caret-host[data-state="open"] .ds-dropdown-caret {
    --ds-shape-morph-target: 1;
    /* Open: the focused INPUT BORDER, not --ui-color-prominent. The open
     * trigger draws that exact border, so caret and outline read as one
     * accent, including the border's own dark-mode value. */
    color: var(--ui-color-input-border-focus);
  }
  .ds-dropdown-caret-host[data-state="open"] .ds-dropdown-caret-chevron {
    rotate: 180deg;
  }
  .ds-dropdown-caret-host:is(:disabled, [aria-disabled="true"], [data-disabled]) .ds-dropdown-caret {
    /* Disabled: the secondary button's disabled BORDER as a fill. The trigger
     * uses the secondary disabled background, so that shade would vanish; the
     * border shade matches the trigger's own disabled border and stays visible. */
    color: var(--ui-color-secondary-border-disabled);
  }
  .ds-dropdown-caret-host:is(:disabled, [aria-disabled="true"], [data-disabled])
    .ds-dropdown-caret-chevron {
    color: var(--ui-color-secondary-foreground);
  }
  /* Content-only fade, for hosts whose surface stays opaque (TypeableDropdownTrigger).
   * A host carrying ds-disabled-state already fades as a whole. */
  .ds-dropdown-caret-host:not(.ds-disabled-state):is(:disabled, [aria-disabled="true"], [data-disabled])
    .ds-dropdown-caret-chevron {
    opacity: var(--ui-opacity-disabled);
  }
  /* The chevron's flip rides the shape-morph spring, which is off the scale,
   * so the global block cannot reach it. Inside this query the scale is
   * already collapsed: this borrows that one reduced duration. */
  @media (prefers-reduced-motion: reduce) {
    .ds-dropdown-caret,
    .ds-dropdown-caret-chevron {
      transition-duration: var(--ui-motion-duration-fast);
    }
  }

  /* RevealChangeText — a slot that slides its content out from one edge and
   * tucks it back under whatever follows. WIDTH is the animated property, not a
   * transform: the point is that the row around it re-centres and re-flows as
   * the slot opens and closes, which a transform (no layout effect) cannot do.
   *
   * `justify-content` is what picks the edge. Pinning the content's RIGHT edge
   * (the default) means narrowing the box eats the content from the LEFT — it
   * tucks under the next element and reveals back out from that same seam.
   *
   * The content keeps its natural width while the slot around it is 0 wide
   * because it is `flex-shrink: 0` and `nowrap`. This is deliberately NOT a
   * `grid-template-columns: 1fr -> 0fr` slot: that sizes rows fine, but for a
   * COLUMN in a shrink-to-fit container the `overflow: hidden` item has an
   * automatic minimum of 0, so `1fr` has no free space to claim and collapses
   * the content to nothing.
   *
   * Timing is on the motion scale, one shared `enter` curve. The reveal
   * (`slower`) is deliberately slower than a roll: it is motion the eye is
   * meant to follow. The collapse (`slow`) is shorter because tucking away is
   * the half nobody needs to read, and because a value CHANGE runs both back
   * to back. One curve, unlike the roll's split pair: both halves are the SAME
   * slot moving, and an accelerating collapse reads as the content being
   * yanked rather than tucked. */
  .ds-reveal-change {
    display: inline-flex;
    align-items: center;
    justify-content: flex-end;
    overflow: hidden;
    width: 0;
    transition: width var(--ui-motion-duration-slow)
      var(--ui-motion-ease-enter);
  }
  .ds-reveal-change[data-direction="right"] {
    justify-content: flex-start;
  }
  /* --ds-reveal-change-width is the measured natural width of the content, set
   * by the component. `auto` is the pre-measurement fallback (first paint, SSR)
   * so the slot is never briefly empty; nothing animates on that first render. */
  .ds-reveal-change[data-open="true"] {
    width: var(--ds-reveal-change-width, auto);
    transition-duration: var(--ui-motion-duration-slower);
  }
  .ds-reveal-change-content {
    display: inline-flex;
    flex-shrink: 0;
    align-items: center;
    white-space: nowrap;
  }

  /* Reduced motion still needs the transition to RUN, just instantly: the
   * content swap at the end of a collapse and the `onSettled` callback both
   * hang off transitionend, and `transition: none` would starve them —
   * stranding the outgoing content on screen forever. The global block in
   * tokens.css collapses the scale to a non-zero instant for exactly this
   * reason, so no rule is needed here. Same trade the rolling text makes. */
}

@keyframes ds-shape-morph-clock {
  from {
    --ds-shape-morph-clock: 0;
  }
  to {
    --ds-shape-morph-clock: 1;
  }
}
@keyframes ds-shape-morph-spin {
  to {
    transform: rotate(360deg);
  }
}

/*
 * Loading spinner keyframes — read by the .ds-spinner-* helpers above.
 *
 * ds-spinner-rotate: one full turn, for every variant's turning group.
 * ds-spinner-dash: the flat arc's Material dash cycle. The stops are
 *   Material's own, rescaled from its 44-unit circle (circumference ≈ 126.9):
 *   dash 1 → 100 → 100 becomes grow 0 → 1 → 1 (min → max sweep), and offset
 *   0 → −15 → −125 becomes tail 0 → 15/126.9 → 125/126.9 of a turn.
 */
@keyframes ds-spinner-rotate {
  to {
    transform: rotate(360deg);
  }
}
@keyframes ds-spinner-dash {
  0% {
    --ds-spinner-grow: 0;
    --ds-spinner-tail: 0;
  }
  50% {
    --ds-spinner-grow: 1;
    --ds-spinner-tail: 0.118;
  }
  100% {
    --ds-spinner-grow: 1;
    --ds-spinner-tail: 0.985;
  }
}

@keyframes ds-shimmer {
  from { background-position: 150% center; }
  to   { background-position: -50% center; }
}
/* --ds-roll-dir (default 1 = downward) flips the travel: RollChangeText sets -1
 * for upward. The old face exits in the travel direction; the new face enters
 * from the opposite side. Depth and blur come from --ui-roll-change-*; the
 * mid-point blur is derived from the same token so the two cannot drift. */
@keyframes ds-roll-out {
  to {
    transform: translateY(calc(var(--ds-roll-dir, 1) * var(--ui-roll-change-depth)));
    filter: blur(var(--ui-roll-change-blur));
    opacity: 0;
  }
}
@keyframes ds-roll-in {
  from {
    transform: translateY(calc(var(--ds-roll-dir, 1) * -1 * var(--ui-roll-change-depth)));
    filter: blur(var(--ui-roll-change-blur));
    opacity: 0;
  }
  60%  { filter: blur(calc(var(--ui-roll-change-blur) * 0.375)); }
  to   { transform: translateY(0); filter: blur(0); opacity: 1; }
}
/* FadeChangeText — ds-roll-out/-in minus the blur. Same --ds-roll-dir sign
 * convention; depth from --ui-fade-change-depth.
 *
 * Opacity runs on its OWN keyframe offsets, not the travel's: the old face is
 * gone by 50% of its roll, the new face holds at 0 for the first 30% of its
 * roll. Sharing the travel's curve (as the blurred roll does) left both faces
 * near-opaque at once — the in-ease is decelerating — and without blur to mask
 * it the two words visibly stacked with no fade at all. Transform is only
 * given at 0%/100%, so it still interpolates as one continuous curve. The
 * offsets are literal because keyframe selectors cannot read var(). */
@keyframes ds-fade-change-out {
  50% { opacity: 0; }
  to {
    transform: translateY(calc(var(--ds-roll-dir, 1) * var(--ui-fade-change-depth)));
    opacity: 0;
  }
}
@keyframes ds-fade-change-in {
  from {
    transform: translateY(calc(var(--ds-roll-dir, 1) * -1 * var(--ui-fade-change-depth)));
    opacity: 0;
  }
  30% { opacity: 0; }
  to { transform: translateY(0); opacity: 1; }
}

/* RollingDigitsText slot enter/exit. Deliberately ONE-SIDED: the missing half of
 * each pair is taken from the element's own computed style, so the same four
 * keyframes drive a digit wheel and a grouping comma — two different resting
 * widths — without either width appearing here. Adding the other half would pin
 * them to one element type and quietly break the other. */
@keyframes ds-rolling-digits-in {
  from { width: 0; }
}
@keyframes ds-rolling-digits-out {
  to { width: 0; }
}
@keyframes ds-rolling-digits-fade-in {
  from { opacity: 0; }
}
@keyframes ds-rolling-digits-fade-out {
  to { opacity: 0; }
}

/* UnderlineLinkText sweep. First half: hold the right edge and shrink to zero so
 * the line exits to the right. At the midpoint the (now zero-width) line jumps
 * its anchor to the left — imperceptible because there is nothing to see — then
 * the second half grows it back from the left. The 0% frame anchors right while
 * the resting style anchors left, but at full width both are identical, so the
 * animation starts without a jump. */
@keyframes ds-underline-wipe {
  0%     { background-size: 100% var(--ds-underline-thickness, var(--ui-underline-link-thickness)); background-position-x: 100%; }
  50%    { background-size: 0% var(--ds-underline-thickness, var(--ui-underline-link-thickness));   background-position-x: 100%; }
  50.01% { background-size: 0% var(--ds-underline-thickness, var(--ui-underline-link-thickness));   background-position-x: 0%; }
  100%   { background-size: 100% var(--ds-underline-thickness, var(--ui-underline-link-thickness)); background-position-x: 0%; }
}

